# -*- coding: utf-8 -*-
# vitrina.py
# ОБОЛОЧКА КЛИЕНТСКОГО БОТА ПО УТВЕРЖДЁННОМУ МАКЕТУ.
# Все экраны рисуются здесь и берут данные только из crm.db.
# Старые экраны клиентского бота перехватываются и больше не показываются.
# CRM-бот не затрагивается вообще.
#
# Запуск: кнопка "Run this file". Потом Tasks → Restart.

import os, io, re, json, time, sqlite3, threading, urllib.request, urllib.parse

BAZA_DIR  = "/home/Carix"
PAPKA_VID = os.path.join(BAZA_DIR, "video")
LOG       = os.path.join(BAZA_DIR, "vitrina_log.txt")

TELEFON   = "[N]"
ADRES     = "ул. Победы 20, Киев"
WHATSAPP  = "[N]"
BRON_USD  = 500
SROK_DNEY = 14
VALYUTA   = "USD"
PLITKOJ   = 6          # до скольких машин показывать карточками с фото

BYUDZHET = ["до 15 000 $", "15 000 – 25 000 $", "25 000 – 40 000 $", "больше 40 000 $"]
KUZOV    = ["седан", "кроссовер / внедорожник", "хэтчбек / универсал", "электро / гибрид"]

_podbor = {}   # кто на каком шаге подбора


def zapis(s):
    try:
        with io.open(LOG, "a", encoding="utf-8") as f:
            f.write("%s %s\n" % (time.strftime("%d.%m %H:%M:%S"), s))
    except Exception:
        pass


def chitat(put):
    with io.open(put, "r", encoding="utf-8", errors="ignore") as f:
        return f.read()


def fajl(imya, po_umolchaniyu=""):
    try:
        return chitat(os.path.join(BAZA_DIR, imya)).strip()
    except Exception:
        return po_umolchaniyu


def karta_url():
    return fajl("karta_ssylka.txt", "[URL]")


def sajt():
    adres = fajl("video_sayt.txt")
    if adres:
        return adres.rstrip("/")
    return "[URL]" % os.path.basename(BAZA_DIR.rstrip("/")).lower()


# ------------------------------------------------------------------ ДАННЫЕ
def mashiny():
    put = os.path.join(BAZA_DIR, "crm.db")
    con = sqlite3.connect("file:%s?mode=ro" % put, uri=True)
    con.row_factory = sqlite3.Row
    try:
        stroki = [dict(r) for r in con.execute("SELECT * FROM cars WHERE published=1 ORDER BY id")]
    finally:
        con.close()
    return stroki


def mashina(nomer_id):
    for m in mashiny():
        if str(m.get("id")) == str(nomer_id):
            return m
    return None


def nomer(m):
    return (m.get("auto_number") or "UA-%04d" % int(m.get("id") or 0)).strip()


def spisok(pole):
    if not pole:
        return []
    try:
        z = json.loads(pole) if isinstance(pole, str) else pole
    except Exception:
        return []
    if not isinstance(z, list):
        return []
    itog = []
    for x in z:
        if isinstance(x, dict):
            x = x.get("file_id") or x.get("id") or x.get("path") or ""
        if x:
            itog.append(str(x))
    return itog


def sklonenie(n):
    if n % 10 == 1 and n % 100 != 11:
        return "день"
    if n % 10 in (2, 3, 4) and n % 100 not in (12, 13, 14):
        return "дня"
    return "дней"


def srok(m):
    """Дни считаются с момента, когда владелец перевёл статус."""
    status = (m.get("status") or "").lower()
    if status.startswith("ua_"):
        return "Машина в Киеве — можно приехать и посмотреть"
    if status == "ge_to_kyiv":
        try:
            pamyat = json.loads(chitat(os.path.join(BAZA_DIR, ".etapy.json")))
            s_kogda = (pamyat.get(nomer(m)) or {}).get("s_kogda")
        except Exception:
            s_kogda = None
        if s_kogda:
            ostalos = SROK_DNEY - int((time.time() - s_kogda) // 86400)
            if ostalos > 0:
                return "До прибытия в Киев — %d %s" % (ostalos, sklonenie(ostalos))
            return "Прибытие в Киев ожидается со дня на день"
        return "В Киеве через %d дней" % SROK_DNEY
    return "Срок прибытия — %d дней после оплаты" % SROK_DNEY


def cena(m):
    c = m.get("price_uah") or m.get("price_total") or 0
    try:
        c = int(float(c))
    except Exception:
        c = 0
    if not c:
        return "цена по запросу"
    krasivo = "{:,}".format(c).replace(",", " ")
    return "%s $" % krasivo if VALYUTA == "USD" else "%s ₴" % krasivo


def etap(m):
    s = (m.get("status") or "").lower()
    if s.startswith("sold"):
        return "уже продана · в пути", False
    if s.startswith("kr_"):
        return "Выкуплена · ожидает погрузки в Корее", False
    if s.startswith("sea_"):
        return "В море · идёт из Кореи", False
    if s == "ge_to_kyiv":
        return "Выехала из Грузии · едет в Киев", True
    if s.startswith("ge_"):
        return "В Грузии · можно забронировать", True
    if s.startswith("ua_"):
        return "В Киеве · можно посмотреть", True
    return "В работе", False


def zagolovok(m):
    return " ".join(str(x) for x in [m.get("brand"), m.get("model"), m.get("year")] if x)


def korotko(m):
    kuski = []
    if m.get("engine_cc"):
        kuski.append("%s см³" % m["engine_cc"])
    if m.get("fuel"):
        kuski.append(str(m["fuel"]))
    if m.get("gearbox"):
        kuski.append(str(m["gearbox"]))
    if m.get("drive"):
        kuski.append(str(m["drive"]))
    if m.get("mileage_km"):
        try:
            kuski.append("{:,} км".format(int(m["mileage_km"])).replace(",", " "))
        except Exception:
            pass
    return " · ".join(kuski)


def oblozhka(m):
    """Сначала кадр, собранный на диске (его Telegram точно покажет), потом file_id."""
    papka = os.path.join(PAPKA_VID, "foto", nomer(m))
    try:
        kadry = sorted(f for f in os.listdir(papka) if f.lower().endswith(".jpg"))
        if kadry:
            return "%s/foto/%s/%s" % (sajt(), nomer(m), kadry[0])
    except Exception:
        pass
    if m.get("cover_photo"):
        return m.get("cover_photo")
    spisok_kadrov = spisok(m.get("photos"))
    return spisok_kadrov[0] if spisok_kadrov else None


def stranica_est(m):
    put = os.path.join(PAPKA_VID, nomer(m) + ".html")
    try:
        return os.path.exists(put) and os.path.getsize(put) > 800
    except Exception:
        return False


# ------------------------------------------------------------------ ЭКРАНЫ
def katalog_url():
    return "%s/katalog.html?v=%d" % (sajt(), int(time.time()))


def katalog_gotov():
    put = os.path.join(PAPKA_VID, "katalog.html")
    try:
        return os.path.exists(put) and os.path.getsize(put) > 800
    except Exception:
        return False


def ekran_start(user_id=None):
    vsego = len(mashiny())
    tekst = (
        "<b>UA ART COMPANY</b> · автомобили из Кореи под ключ\n"
        "В наличии и в пути — <b>%d</b>. Цена под ключ, доплат нет." % vsego
    )
    if katalog_gotov():
        knopki = []  # CLIENT-TERMS-001: «Условия и гарантии» removed (owner [N])
    else:
        knopki = [
            [("Авто в наличии и в пути", "v_cars")],
            [("Подобрать под заказ", "v_podbor")],
            [("Как мы работаем", "v_kak"), ("Контакты", "v_kontakty")],
        ]
    # UA-ANALIT-KNOPKA-V2 · раздел аналитики виден только владельцу
    if user_id is not None and str(user_id) == fajl("vladelec.txt"):
        import ua_lead_desk  # LEAD-FOLDERS-001: leads by folder
        knopki = list(knopki) + [[(ua_lead_desk.BUTTON, ua_lead_desk.CALLBACK)], [('📊 Аналитика', 'v_analytics')]]
    return tekst, knopki


# UA-V126 · подбор под заказ из пяти стран
STRANY_PODBOR = [
    ("korea", "Корея", "Кореи", "🇰🇷"),
    ("japan", "Япония", "Японии", "🇯🇵"),
    ("usa", "Америка", "Америки", "🇺🇸"),
    ("europe", "Европа", "Европы", "🇪🇺"),
    ("china", "Китай", "Китая", "🇨🇳"),
]
STRANY_IMENA = dict((kod, imya) for kod, imya, rod, flag in STRANY_PODBOR)


def knopki_stran():
    """Пять кнопок подбора — по одной на страну."""
    t = int(time.time())
    return [[("%s  Подбор из %s" % (flag, rod),
              "%s/podbor.html?strana=%s&v=%d" % (sajt(), kod, t))]
            for kod, imya, rod, flag in STRANY_PODBOR]


def zapis_strany(kto, chat_id, strana, dannye):
    """Заявка на подбор пишется в crm.db — таблица podbor_zayavki."""
    try:
        import sqlite3
        b = sqlite3.connect("/home/Carix/crm.db", timeout=10)
        b.execute("CREATE TABLE IF NOT EXISTS podbor_zayavki ("
                  "id INTEGER PRIMARY KEY AUTOINCREMENT, kogda TEXT, chat_id TEXT, "
                  "kto TEXT, strana TEXT, byudzhet TEXT, kuzov TEXT, marka TEXT)")
        b.execute("INSERT INTO podbor_zayavki "
                  "(kogda, chat_id, kto, strana, byudzhet, kuzov, marka) "
                  "VALUES (?,?,?,?,?,?,?)",
                  (time.strftime("%Y-%m-%d %H:%M:%S"), str(chat_id), str(kto), strana,
                   str(dannye.get("b") or ""), str(dannye.get("k") or ""),
                   str(dannye.get("m") or "")))
        b.commit()
        b.close()
    except Exception as e:
        try:
            zapis("strana: %s" % e)
        except Exception:
            pass

async def privetstvie(bot, chat_id):
    """Первое, что видит человек, придя со страницы: кто с ним говорит."""
    await poslat(bot, chat_id,
                 "<b>UA ART COMPANY LLC</b>\n"
                 "<i>автомобили из Кореи под ключ</i>\n\n"
                 "Здравствуйте! Вы на связи с компанией.\n"
                 "Цена фиксируется в договоре: выкуп на аукционе, доставка, "
                 "растаможка и сертификат — уже в стоимости.")


def ekran_kak():
    tekst = (
        "<b>7 шагов до вашего авто</b>\n\n"
        "1 · Подбираем варианты под бюджет\n"
        "2 · Проверяем историю и отчёт аукциона\n"
        "3 · Выкупаем — предоплата %d $\n"
        "4 · Стоянка в Корее, ждём погрузку\n"
        "5 · Море: Корея → Грузия\n"
        "6 · Поти/Батуми: оформление\n"
        "7 · Киев: растаможка, сертификат, выдача\n\n"
        "<i>Цена в договоре фиксируется на шаге 3 и дальше не меняется.</i>" % BRON_USD
    )
    return tekst, [[("Авто в наличии и в пути", "v_cars")], [("Контакты", "v_kontakty")]]


def ekran_kontakty():
    tekst = (
        "<b>Контакты</b>\n\n"
        "Менеджер Артём\n"
        "%s\n"
        "%s\n\n"
        "Пишите сюда — сообщение попадёт менеджеру." % (TELEFON, ADRES)
    )
    return tekst, [[("Офис на карте", karta_url())], [("Назад", "v_start")]]


def ekran_bron(m):
    tekst = (
        "<b>Бронь принята</b>\n\n"
        "%s · %s\n"
